-- The arp as a factory module (#739, step 6 of the audio foundation #713): deck/modules/arp/src/lib.rs becomes the catalog
-- document `module:arp` marked `factory: true`, as the small audio modules did in 2026-11-21-factory-audio-modules: read-only, a
-- member derives a module of their own from it. Source only: `files` is the repository's file byte for byte (server
-- tests/Unit/Domain/FactoryModulesTest keeps them equal).
-- The wasm: NOT in this file. It reads as not compiled (no descriptor / wasm, so it is no kind in GET /api/kinds yet) until an
-- admin presses Compile on it in the creator's Sound workspace (POST /api/modules/compile { factory: "arp" }). ORDER: the build
-- service must carry this deploy's SDK first (`deck_module::dsp::arp`) – with an older SDK it does not build.
-- Stored data: nothing else changes. deck-events' `arp` generator (inside an `events` node's patch) keeps its stored form and
-- now plays the module's rule; `mode = "played"` is new there, no stored value changes meaning.
-- What it touches:
--   catalog_modules: one row, INSERT IGNORE – an existing row `arp` (a module a creator made under the name) is left as it is,
--     and then `arp` is not a factory module (the dry run below shows it; tell the owner).
--   entity_versions: the factory content as the published version of `module:arp` (message = the marker below); a published
--     version of that key from before becomes a draft (history).
-- Dry run (before): SELECT id, JSON_EXTRACT(data, '$.factory') AS factory FROM catalog_modules WHERE id = 'arp';
--   -> expected: no rows. SELECT entity_key, status, COUNT(*) FROM entity_versions WHERE entity_key = 'module:arp' GROUP BY entity_key, status;
--   -> expected: no rows (else: published versions that become history).
-- Test (after): SELECT id, JSON_EXTRACT(data, '$.factory'), JSON_LENGTH(data, '$.files') FROM catalog_modules WHERE id = 'arp';
--   -> one row, true 1; SELECT entity_key FROM entity_versions WHERE status = 'published' AND message = 'factory module (migration 2026-11-22-factory-arp)';
--   -> one row.
-- Plan's row counts on a database without it: 1 . 0 . 1. MariaDB 10.11, idempotent: a second run changes nothing (INSERT IGNORE;
-- the published marker version exists). Escaping: plain string literals (no NO_BACKSLASH_ESCAPES): `\\` is one backslash of the
-- JSON, `\'` a quote; the row is one line.

INSERT IGNORE INTO `catalog_modules` (`id`, `position`, `data`, `updated_at`, `updated_by`) VALUES
  ('arp', 12, '{"id":"arp","name":"arp","factory":true,"files":{"lib.rs":"//! `arp` – an arpeggiator: the notes held on `notes` (a note on at key down, its off at key up) leave one after another\\n//! on `out`, a note a step, up, down, up and down or in the order they were played, through `octaves`, moved by\\n//! `transpose`. Step `k` plays at beat `k / rate` and its number alone picks the note (the SDK\'s `dsp::arp`, the one\\n//! copy deck-events\' `arp` generator plays too), so the pattern is on the beat grid however the blocks are cut. A step\\n//! lasts `gate` of itself; with `latch` on the released keys keep playing until a key is pressed again. A reset ends\\n//! the set and passes on.\\n//!\\n//! Build: `cargo build --release --target wasm32-unknown-unknown -p arp-module` (the .wasm in\\n//! `target/wasm32-unknown-unknown/release/arp_module.wasm`).\\n// one `#[port(…)]` a port: clippy takes them for duplicates (deck/module/README.md)\\n#![allow(clippy::duplicated_attributes)]\\nuse deck_module::dsp::arp::{steps, Held, Mode, Note};\\nuse deck_module::{math, Block, Ctx, Ev, Kind, Module};\\n\\n/// steps a beat of each `rate` choice\\nconst RATES: [f64; 9] = [0.25, 0.5, 1.0, 1.5, 2.0, 3.0, 4.0, 6.0, 8.0];\\n\\n#[derive(Module)]\\n#[module(name = \\"arp\\", doc = \\"an arpeggiator: the held notes one after another on the beat grid\\")]\\n#[port(input, event, name = \\"notes\\", names = \\"music.note\\", props = \\"pitch|vel|glide|key\\", capacity = 64, doc = \\"the held notes: a note on at key down, its off at key up\\")]\\n#[port(output, event, name = \\"out\\", names = \\"music.note\\", props = \\"pitch|vel|glide|key\\", capacity = 64, doc = \\"a note a step\\")]\\n#[preset(name = \\"crow\\", doc = \\"Up in eighths over two octaves, each note half a step long.\\", values(octaves = 2.0))]\\npub struct Arp {\\n    #[param(choices = \\"up|down|updown|played\\", default = 0, doc = \\"up: low to high; down; updown: up and back; played: in the order the keys went down\\")]\\n    pub mode: f32,\\n    #[param(choices = \\"1/1|1/2|1/4|1/4t|1/8|1/8t|1/16|1/16t|1/32\\", default = 4, doc = \\"the step as a note value (t = a triplet)\\")]\\n    pub rate: f32,\\n    #[param(range = 5.0..100.0, default = 50.0, unit = \\"%\\", doc = \\"how long a note holds, of its step\\")]\\n    pub gate: f32,\\n    #[param(range = 1.0..4.0, default = 1.0, unit = \\"oct\\", doc = \\"how many octaves the pattern climbs\\")]\\n    pub octaves: f32,\\n    #[param(range = -24.0..24.0, default = 0.0, unit = \\"st\\", doc = \\"every note moved by semitones\\")]\\n    pub transpose: f32,\\n    #[param(choices = \\"off|on\\", default = 0, doc = \\"on: released keys keep playing until a key is pressed again\\")]\\n    pub latch: f32,\\n    held: Held,\\n}\\n\\nimpl Arp {\\n    /// steps a beat\\n    pub fn per_beat(&self) -> f64 {\\n        RATES[(math::round(self.rate).max(0.0) as usize).min(RATES.len() - 1)]\\n    }\\n\\n    fn event(&mut self, block: &mut Block, e: &Ev) {\\n        match e.kind() {\\n            Some(Kind::NoteOn) => self.held.press(Note { id: e.id, hz: e.pitch_hz(), key: e.key(), velocity: e.velocity(), glide: e.glide() }),\\n            Some(Kind::NoteOff) => self.held.release(e.id),\\n            Some(Kind::Reset) => {\\n                self.held.clear();\\n                block.emit(Self::OUT, Ev::reset(e.frame));\\n            }\\n            _ => {}\\n        }\\n    }\\n}\\n\\nimpl Module for Arp {\\n    fn process(&mut self, block: &mut Block, ctx: &Ctx) {\\n        self.held.set_latch(self.latch >= 0.5);\\n        let mode = Mode::from_index(math::round(self.mode));\\n        let octaves = math::round(self.octaves).clamp(1.0, 4.0) as u32;\\n        let per_beat = self.per_beat();\\n        let len = (f64::from(self.gate) / 100.0 / per_beat) as f32;\\n        let tempo = ctx.tempo();\\n        let start = ctx.frame();\\n        // a step belongs to the call its rounded frame falls in: every cut plays it on the same frame\\n        let (from, to) = (tempo.beat_at(start - 0.5), tempo.beat_at(start + ctx.frames() as f64 - 0.5));\\n        let input = block.events_in(Self::NOTES);\\n        let mut next = 0;\\n        for (k, beat) in steps(from, to, per_beat) {\\n            let Some(at) = tempo.frame_of(beat) else { break };\\n            let frame = (at - start + 0.5).max(0.0) as u32;\\n            // what arrived up to the step\'s frame plays in it\\n            while next < input.len() && input[next].frame <= frame {\\n                self.event(block, &input[next]);\\n                next += 1;\\n            }\\n            if let Some((note, octave)) = self.held.step(k, mode, octaves) {\\n                let n = note.moved(12.0 * f64::from(octave) + f64::from(self.transpose));\\n                // the step is the note\'s id\\n                block.emit(Self::OUT, Ev::note_on(frame, k as u32, n.hz, n.key, n.velocity).gliding(n.glide).lasting(len));\\n            }\\n        }\\n        for e in &input[next..] {\\n            self.event(block, e);\\n        }\\n    }\\n}\\n"}}', UTC_TIMESTAMP(), 'migration:2026-11-22-factory-arp');

-- an earlier published version of the key becomes history (only where the factory row is ours)
UPDATE `entity_versions` SET `status` = 'draft'
 WHERE `entity_key` = 'module:arp' AND `status` = 'published'
   AND COALESCE(`message`, '') <> 'factory module (migration 2026-11-22-factory-arp)'
   AND EXISTS (SELECT 1 FROM `catalog_modules` m WHERE CONCAT('module:', m.`id`) COLLATE utf8mb4_general_ci = `entity_versions`.`entity_key`
               AND JSON_CONTAINS(m.`data`, 'true', '$.factory'));

-- the factory content as the published version (the creator's document)
INSERT INTO `entity_versions` (`entity_key`, `kind`, `toon`, `locale`, `json`, `author`, `created_at`, `status`, `message`)
SELECT CONCAT('module:', m.`id`), 'module', NULL, NULL, m.`data`, NULL, UTC_TIMESTAMP(), 'published', 'factory module (migration 2026-11-22-factory-arp)'
  FROM `catalog_modules` m
 WHERE m.`id` = 'arp' AND JSON_CONTAINS(m.`data`, 'true', '$.factory')
   AND NOT EXISTS (SELECT 1 FROM `entity_versions` e WHERE e.`entity_key` = CONCAT('module:', m.`id`) COLLATE utf8mb4_general_ci
                   AND e.`message` = 'factory module (migration 2026-11-22-factory-arp)');
